/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { BuildScreen } from "../../src/build/BuildScreen.js";
import { ChallengeScreen } from "../../src/challenge/ChallengeScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import LewisStructuresColors from "../../src/LewisStructuresColors.js";
import { LewisStructuresPreferencesModel } from "../../src/preferences/LewisStructuresPreferencesModel.js";
import { ResonanceScreen } from "../../src/resonance/ResonanceScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from lewisStructuresQueryParameters.
  const simPreferences = new LewisStructuresPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new BuildScreen(simPreferences, {
      name: stringManager.getScreenNames().buildStringProperty,
      tandem: Tandem.ROOT.createTandem("buildScreen"),
      backgroundColorProperty: LewisStructuresColors.backgroundColorProperty,
    }),
    new ResonanceScreen(simPreferences, {
      name: stringManager.getScreenNames().resonanceStringProperty,
      tandem: Tandem.ROOT.createTandem("resonanceScreen"),
      backgroundColorProperty: LewisStructuresColors.backgroundColorProperty,
    }),
    new ChallengeScreen(simPreferences, {
      name: stringManager.getScreenNames().challengeStringProperty,
      tandem: Tandem.ROOT.createTandem("challengeScreen"),
      backgroundColorProperty: LewisStructuresColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { LewisStructuresColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
